// Open conversations visible to the viewer whose last message is the
// customer's (waiting for an answer), longest waiting first.
func (q *Queries) OpsWaitingReply(ctx context.Context, arg OpsWaitingReplyParams) ([]OpsWaitingReplyRow, error) {
	rows, err := q.db.Query(ctx, opsWaitingReply, arg.SeeAll, arg.ViewerID, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OpsWaitingReplyRow{}
	for rows.Next() {
		var i OpsWaitingReplyRow
		if err := rows.Scan(
			&i.ID,
			&i.ContactID,
			&i.AssigneeID,
			&i.LastInboundAt,
			&i.UnreadCount,
			&i.OwnerType,
			&i.PhoneE164,
			&i.ContactName,
			&i.AssigneeName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
